package dev.newenchantmentsystem.api;

import net.minecraftforge.common.ForgeConfigSpec;

/**
 * Mod runtime configuration.
 * Generated by Forge on first launch at: config/new_enchantment_system-common.toml
 * This is a COMMON config (shared between client and server); restart is required to apply changes.
 */
public class Config {

    private static final ForgeConfigSpec.Builder BUILDER = new ForgeConfigSpec.Builder();

    // ========== Enchantment Core ==========

    /** Multiplier of enchantment cost (XP & lapis). */
    public static final ForgeConfigSpec.DoubleValue ENCHANTMENT_COST_MULTIPLIER;

    // ========== Efficiency (Max Level & Speed Bonus) ==========

    /** Low-tier max enchantment level. */
    public static final ForgeConfigSpec.IntValue LOW_MAX_LEVEL;
    /** Medium-tier max enchantment level. */
    public static final ForgeConfigSpec.IntValue MEDIUM_MAX_LEVEL;
    /** High-tier max enchantment level. */
    public static final ForgeConfigSpec.IntValue HIGH_MAX_LEVEL;
    /** Which tier the Efficiency enchantment uses for its max level (low / medium / high). */
    public static final ForgeConfigSpec.ConfigValue<String> EFFICIENCY_MAX_LEVEL_TIER;
    /** Coefficient (EfficiencyCoefficient) of the linear speed bonus: E+ = coefficient * level + constant. */
    public static final ForgeConfigSpec.DoubleValue EFFICIENCY_COEFFICIENT;
    /** Constant (EfficiencyConstant) of the linear speed bonus: E+ = coefficient * level + constant. */
    public static final ForgeConfigSpec.DoubleValue EFFICIENCY_CONSTANT;

    // ========== Vanilla Integration ==========

    /** Whether custom enchantments may appear in the vanilla enchanting table. */
    public static final ForgeConfigSpec.BooleanValue ENABLE_ENCHANTING_TABLE_INTEGRATION;
    /** Whether villagers may trade custom enchanted books. */
    public static final ForgeConfigSpec.BooleanValue ENABLE_VILLAGER_INTEGRATION;
    /** Whether custom enchanted books may appear in loot chests. */
    public static final ForgeConfigSpec.BooleanValue ENABLE_LOOT_INTEGRATION;

    // ========== Vanilla Enchantment Control ==========

    /** Whether the vanilla Mending enchantment is enabled. Default false = ban Mending. */
    public static final ForgeConfigSpec.BooleanValue ENABLE_MENDING;
    /** Whether the vanilla Fire Protection enchantment is enabled. Default false = ban Fire Protection. */
    public static final ForgeConfigSpec.BooleanValue ENABLE_FIRE_PROTECTION;
    /** Whether golden equipment/tools/weapons repair from XP orbs without the Mending enchantment. */
    public static final ForgeConfigSpec.BooleanValue GOLDEN_MENDING;
    /** Durability repaired by the Mending enchantment per XP point. Vanilla default: 2.0. */
    public static final ForgeConfigSpec.DoubleValue MENDING_XP_REPAIR_RATIO;
    /** Inventory scan interval (in ticks). Larger values reduce lag. */
    public static final ForgeConfigSpec.IntValue SCAN_INTERVAL;

    // ========== Combat Tuning ==========

    /** Damage reduction per level of the Protection enchantment (all damage types). */
    public static final ForgeConfigSpec.DoubleValue PROTECTION_PER_LEVEL;
    /** Damage reduction per level of Magic / Projectile / Blast / Feather Falling protection. */
    public static final ForgeConfigSpec.DoubleValue SPECIAL_PROTECTION_PER_LEVEL;
    /** Melee damage multiplier per level of Sharpness (all targets). */
    public static final ForgeConfigSpec.DoubleValue SHARPNESS_DAMAGE_MULTIPLIER;
    /** Melee damage multiplier per level of Smite (undead targets). */
    public static final ForgeConfigSpec.DoubleValue SMITE_DAMAGE_MULTIPLIER;
    /** Melee damage multiplier per level of Bane of Arthropods (arthropod targets). */
    public static final ForgeConfigSpec.DoubleValue BANE_OF_ARTHROPODS_DAMAGE_MULTIPLIER;
    /** Damage multiplier per level of Impaling (aquatic targets; melee & thrown trident). */
    public static final ForgeConfigSpec.DoubleValue IMPALING_DAMAGE_MULTIPLIER;
    /** Arrow damage multiplier per level of Power (bow). */
    public static final ForgeConfigSpec.DoubleValue POWER_DAMAGE_MULTIPLIER;
    /** Base sweep attack damage ratio (no Sweeping Edge). */
    public static final ForgeConfigSpec.DoubleValue SWEEPING_BASE_RATIO;
    /** Extra sweep attack damage ratio per Sweeping Edge level. */
    public static final ForgeConfigSpec.DoubleValue SWEEPING_EDGE_PER_LEVEL;
    /** Extra knockback distance contributed by the Knockback enchantment. */
    public static final ForgeConfigSpec.IntValue KNOCKBACK_BONUS;
    /** Critical damage multiplier per level of the Critical Blade enchantment. */
    public static final ForgeConfigSpec.DoubleValue CRITICAL_BLADE_MULTIPLIER;

    // ========== High Jump ==========

    /** Jump height bonus per level of the High Jump enchantment (0.10 = +10% height per level). */
    public static final ForgeConfigSpec.DoubleValue HIGH_JUMP_JUMP_HEIGHT_BONUS;
    /** Fall safe-distance bonus per level of the High Jump enchantment (0.10 = +10% safe distance per level). */
    public static final ForgeConfigSpec.DoubleValue HIGH_JUMP_FALL_SAFE_DISTANCE_BONUS;

    // ========== Level XP System ==========

    /** Master switch of the level XP system (linear level-up formula & /sep command). */
    public static final ForgeConfigSpec.BooleanValue ENABLE_LEVEL_SYSTEM;
    /** Coefficient (LevelCoefficient) of the linear formula: EP(LV) = coefficient * (LV + constant). */
    public static final ForgeConfigSpec.IntValue LEVEL_COEFFICIENT;
    /** Constant (LevelConstant) of the linear formula: EP(LV) = coefficient * (LV + constant). */
    public static final ForgeConfigSpec.IntValue LEVEL_CONSTANT;

    // ========== Anvil Cost (Tier-based) ==========

    /** Master switch: replace the vanilla rarity-based anvil merge cost with the tier-based one. */
    public static final ForgeConfigSpec.BooleanValue ANVIL_TIER_COST;
    /** Anvil merge cost per level for high-tier enchantments. Allowed: 1 / 2 / 4 / 8. */
    public static final ForgeConfigSpec.IntValue ANVIL_COST_HIGH_TIER;
    /** Anvil merge cost per level for medium-tier enchantments. Allowed: 1 / 2 / 4 / 8. */
    public static final ForgeConfigSpec.IntValue ANVIL_COST_MEDIUM_TIER;
    /** Anvil merge cost per level for low-tier enchantments. Allowed: 1 / 2 / 4 / 8. */
    public static final ForgeConfigSpec.IntValue ANVIL_COST_LOW_TIER;
    /** Master rule: true removes the repair penalty and the "Too Expensive" 40-level cap. */
    public static final ForgeConfigSpec.BooleanValue ANVIL_REPAIR_COST_RULE;
    /** "Too Expensive" threshold used when ANVIL_REPAIR_COST_RULE is false. */
    public static final ForgeConfigSpec.IntValue ANVIL_TOO_EXPENSIVE_THRESHOLD;

    public static final ForgeConfigSpec SPEC;

    static {
        BUILDER.comment("New Enchantment System configuration.",
                        "Auto-generated by the mod; restart is required to apply changes.")
                .push("enchantment");

        ENCHANTMENT_COST_MULTIPLIER = BUILDER
                .comment("Multiplier of enchantment cost (XP & lapis). 1.0 equals vanilla.")
                .defineInRange("enchantmentCostMultiplier", 1.0D, 0.1D, 10.0D);

        BUILDER.pop();

        BUILDER.push("integration");

        ENABLE_ENCHANTING_TABLE_INTEGRATION = BUILDER
                .comment("Allow custom enchantments to appear in the vanilla enchanting table.")
                .define("enableEnchantingTableIntegration", true);

        ENABLE_VILLAGER_INTEGRATION = BUILDER
                .comment("Allow villagers to trade custom enchanted books.")
                .define("enableVillagerIntegration", true);

        ENABLE_LOOT_INTEGRATION = BUILDER
                .comment("Allow custom enchanted books to appear in loot chests.")
                .define("enableLootIntegration", true);

        BUILDER.pop();

        BUILDER.push("vanilla_enchantment");

        ENABLE_MENDING = BUILDER
                .comment("Whether the vanilla Mending enchantment is enabled.",
                        "Default false, i.e. Mending is banned:",
                        "  - No longer generated by enchanting tables, loot or villager trades;",
                        "  - Hidden from the creative inventory;",
                        "  - Existing Mending items in players' inventories are auto-removed.",
                        "Set to true to restore vanilla behaviour.")
                .define("enableMending", false);

        ENABLE_FIRE_PROTECTION = BUILDER
                .comment("Whether the vanilla Fire Protection enchantment is enabled.",
                        "Default false, i.e. Fire Protection is banned (same mechanism as Mending):",
                        "  - No longer generated by enchanting tables, loot or villager trades;",
                        "  - Hidden from the creative inventory;",
                        "  - Existing Fire Protection items in players' inventories are auto-removed.",
                        "Fire damage is now covered by Magic Protection (elemental damage is",
                        "classified into the magic damage category).",
                        "Set to true to restore vanilla behaviour.")
                .define("enableFireProtection", false);

        GOLDEN_MENDING = BUILDER
                .comment("Whether golden equipment/tools/weapons repair from XP orbs on their own",
                        "without needing the Mending enchantment (hidden effect, no enchantment shown).",
                        "Independent from enableMending. Default: true.")
                .define("goldenMending", true);

        MENDING_XP_REPAIR_RATIO = BUILDER
                .comment("Durability repaired by the Mending enchantment per XP point.",
                        "Vanilla default: 2.0 (1 XP repairs 2 durability).",
                        "Examples: 4.0 repairs faster, 0.5 repairs slower.",
                        "Must be greater than 0.")
                .defineInRange("mendingXpRepairRatio", 2.0D, 0.001D, 100.0D);

        SCAN_INTERVAL = BUILDER
                .comment("Inventory scan interval in ticks (1 second = 20 ticks).",
                        "The Mending purger scans the whole inventory every N ticks.",
                        "Increase on laggy machines or with many players, e.g. 20 (once per second).")
                .defineInRange("scanInterval", 10, 1, 200);

        BUILDER.pop();

        BUILDER.push("combat");

        PROTECTION_PER_LEVEL = BUILDER
                .comment("Damage reduction per level of the Protection enchantment (all damage types).",
                        "Default: 0.015 (1.5% per level).")
                .defineInRange("protectionPerLevel", 0.015D, 0.0D, 1.0D);

        SPECIAL_PROTECTION_PER_LEVEL = BUILDER
                .comment("Damage reduction per level of Magic Protection, Projectile Protection,",
                        "Blast Protection and Feather Falling. All stack additively with Protection.",
                        "Default: 0.03 (3% per level).")
                .defineInRange("specialProtectionPerLevel", 0.03D, 0.0D, 1.0D);

        SHARPNESS_DAMAGE_MULTIPLIER = BUILDER
                .comment("Melee damage multiplier per level of Sharpness (all targets).",
                        "Default: 0.10 (+10% per level).")
                .defineInRange("sharpnessDamageMultiplier", 0.10D, 0.0D, 10.0D);

        SMITE_DAMAGE_MULTIPLIER = BUILDER
                .comment("Melee damage multiplier per level of Smite (undead targets only).",
                        "Default: 0.20 (+20% per level).")
                .defineInRange("smiteDamageMultiplier", 0.20D, 0.0D, 10.0D);

        BANE_OF_ARTHROPODS_DAMAGE_MULTIPLIER = BUILDER
                .comment("Melee damage multiplier per level of Bane of Arthropods (arthropod targets only).",
                        "Default: 0.30 (+30% per level).")
                .defineInRange("baneOfArthropodsDamageMultiplier", 0.30D, 0.0D, 10.0D);

        IMPALING_DAMAGE_MULTIPLIER = BUILDER
                .comment("Damage multiplier per level of Impaling (aquatic targets only).",
                        "Applies to both melee (sword) and thrown trident attacks.",
                        "Default: 0.20 (+20% per level).")
                .defineInRange("impalingDamageMultiplier", 0.20D, 0.0D, 10.0D);

        POWER_DAMAGE_MULTIPLIER = BUILDER
                .comment("Arrow damage multiplier per level of Power (bow).",
                        "Default: 0.15 (+15% per level).")
                .defineInRange("powerDamageMultiplier", 0.15D, 0.0D, 10.0D);

        SWEEPING_BASE_RATIO = BUILDER
                .comment("Base sweep attack damage ratio (no Sweeping Edge).",
                        "Default: 0.35 (35% of the main hit).")
                .defineInRange("sweepingBaseRatio", 0.35D, 0.0D, 1.0D);

        SWEEPING_EDGE_PER_LEVEL = BUILDER
                .comment("Extra sweep attack damage ratio per Sweeping Edge level.",
                        "Default: 0.10 (+10% per level).")
                .defineInRange("sweepingEdgePerLevel", 0.10D, 0.0D, 1.0D);

        KNOCKBACK_BONUS = BUILDER
                .comment("Extra knockback distance contributed by the Knockback enchantment.",
                        "Total knockback strength = enchantment level + this bonus.",
                        "Default: 2.")
                .defineInRange("knockbackBonus", 2, 0, 100);

        CRITICAL_BLADE_MULTIPLIER = BUILDER
                .comment("Critical damage multiplier per level of the Critical Blade enchantment.",
                        "Default: 0.25 (+25% per level).")
                .defineInRange("criticalBladeMultiplier", 0.25D, 0.0D, 10.0D);

        BUILDER.pop();

        BUILDER.push("high_jump");

        HIGH_JUMP_JUMP_HEIGHT_BONUS = BUILDER
                .comment("Jump height bonus per level of the High Jump enchantment.",
                        "The vertical jump speed is scaled by sqrt(1 + bonus * level), which makes",
                        "the jump height exactly (1 + bonus * level) times higher (h = v^2 / 2g).",
                        "Default: 0.10 (+10% jump height per level).")
                .defineInRange("highJumpJumpHeightBonus", 0.10D, 0.0D, 1.0D);

        HIGH_JUMP_FALL_SAFE_DISTANCE_BONUS = BUILDER
                .comment("Fall safe-distance bonus per level of the High Jump enchantment.",
                        "Vanilla safe distance is 3.0 blocks; with this it becomes 3.0 * (1 + bonus * level).",
                        "Applied via LivingFallEvent (distance is reduced by 3.0 * bonus) before",
                        "calculateFallDamage, so both the vanilla formula and New-Armor-System's",
                        "mass formula receive the reduced distance and stack. Default: 0.10 (+10% safe distance per level).")
                .defineInRange("highJumpFallSafeDistanceBonus", 0.10D, 0.0D, 1.0D);

        BUILDER.pop();

        BUILDER.push("efficiency");

        LOW_MAX_LEVEL = BUILDER
                .comment("Low-tier max enchantment level.",
                        "Many LOW-tier enchantments are toggle-type: extra levels have no",
                        "additional effect (e.g. Silk Touch, Infinity, Channeling, Mending,",
                        "Stable Footing, Worker Exploitation, Golden Glitter). This is one of",
                        "the reasons they are grouped into the low tier, whose default max",
                        "level is 1.")
                .defineInRange("lowMaxLevel", 1, 1, 255);

        MEDIUM_MAX_LEVEL = BUILDER
                .comment("Medium-tier max enchantment level.")
                .defineInRange("mediumMaxLevel", 4, 1, 255);

        HIGH_MAX_LEVEL = BUILDER
                .comment("High-tier max enchantment level.")
                .defineInRange("highMaxLevel", 10, 1, 255);

        EFFICIENCY_MAX_LEVEL_TIER = BUILDER
                .comment("Which tier the Efficiency enchantment uses for its max level.",
                        "Allowed values: low, medium, high. Default: high (uses highMaxLevel = 10).")
                .define("efficiencyMaxLevelTier", "high",
                        value -> "low".equals(value) || "medium".equals(value) || "high".equals(value));

        EFFICIENCY_COEFFICIENT = BUILDER
                .comment("Coefficient of the linear Efficiency speed bonus formula.",
                        "Speed bonus E+ = coefficient * level + constant (replaces vanilla level^2 + 1).",
                        "Default: 2.5.")
                .defineInRange("efficiencyCoefficient", 2.5D, 0.1D, 100.0D);

        EFFICIENCY_CONSTANT = BUILDER
                .comment("Constant of the linear Efficiency speed bonus formula.",
                        "Speed bonus E+ = coefficient * level + constant (replaces vanilla level^2 + 1).",
                        "Default: 1.0.")
                .defineInRange("efficiencyConstant", 1.0D, 0.0D, 100.0D);

        BUILDER.pop();

        BUILDER.push("level_system");

        ENABLE_LEVEL_SYSTEM = BUILDER
                .comment("Master switch of the level XP system (linear level-up formula & /sep command).")
                .define("enableLevelSystem", true);

        LEVEL_COEFFICIENT = BUILDER
                .comment("Coefficient (LevelCoefficient) of the linear level-up formula.",
                        "XP to level up from LV to LV+1: EP(LV) = coefficient * (LV + constant).",
                        "Default: 4.")
                .defineInRange("levelCoefficient", 4, 1, 1000000);

        LEVEL_CONSTANT = BUILDER
                .comment("Constant (LevelConstant) of the linear level-up formula.",
                        "XP to level up from LV to LV+1: EP(LV) = coefficient * (LV + constant).",
                        "Default: 2.")
                .defineInRange("levelConstant", 2, 0, 1000000);

        BUILDER.pop();

        BUILDER.push("anvil");

        ANVIL_TIER_COST = BUILDER
                .comment("Replace the vanilla rarity-based anvil merge cost with a tier-based cost:",
                        "  mergeCost += tierWeight * mergedLevel  (vanilla: rarityWeight * mergedLevel).",
                        "Tier weights are configured below (anvilCostHighTier / anvilCostMediumTier /",
                        "anvilCostLowTier). Merging an enchantment book still costs half (min 1).",
                        "Default: true.")
                .define("anvilTierCost", true);

        ANVIL_COST_HIGH_TIER = BUILDER
                .comment("Anvil merge cost per level for HIGH-tier enchantments",
                        "(Sharpness, Power, Protection family, ...).",
                        "Only 1 / 2 / 4 / 8 map to the vanilla rarity tiers (COMMON / UNCOMMON /",
                        "RARE / VERY_RARE); any other value falls back to the vanilla rarity cost.",
                        "Default: 1.")
                .defineInRange("anvilCostHighTier", 1, 1, 8);

        ANVIL_COST_MEDIUM_TIER = BUILDER
                .comment("Anvil merge cost per level for MEDIUM-tier enchantments",
                        "(Fortune, Looting, Knockback, ...).",
                        "Only 1 / 2 / 4 / 8 map to the vanilla rarity tiers (COMMON / UNCOMMON /",
                        "RARE / VERY_RARE); any other value falls back to the vanilla rarity cost.",
                        "Default: 2.")
                .defineInRange("anvilCostMediumTier", 2, 1, 8);

        ANVIL_COST_LOW_TIER = BUILDER
                .comment("Anvil merge cost per level for LOW-tier enchantments",
                        "(Silk Touch, Infinity, Channeling, Critical Blade, Stable Footing,",
                        "Worker Exploitation, Golden Glitter, ...).",
                        "Only 1 / 2 / 4 / 8 map to the vanilla rarity tiers (COMMON / UNCOMMON /",
                        "RARE / VERY_RARE); any other value falls back to the vanilla rarity cost.",
                        "Note: LOW-tier enchantments are mostly toggle-type (extra levels",
                        "have no effect) and have max level 1 by default, so merging them can",
                        "never raise the level and is pointless; this weight is provided for",
                        "completeness only.",
                        "Default: 4.")
                .defineInRange("anvilCostLowTier", 4, 1, 8);

        ANVIL_REPAIR_COST_RULE = BUILDER
                .comment("Remove the anvil repair-penalty accumulation and the \"Too Expensive\"",
                        "cap so that high-level (tier-based) enchantments can still be merged:",
                        "  true  - no repair penalty, the 40-level cap never triggers.",
                        "  false - vanilla-like behavior, cap configurable via tooExpensiveThreshold",
                        "          below (default 40 = vanilla).",
                        "Independent copy of New-Armor-System's anvilRepairCostRule; when that mod",
                        "is also loaded, AnvilMenuCapMixin is skipped and the armor mod's own rule",
                        "applies instead.",
                        "Default: true.")
                .define("anvilRepairCostRule", true);

        ANVIL_TOO_EXPENSIVE_THRESHOLD = BUILDER
                .comment("\"Too Expensive\" threshold in levels; only used when anvilRepairCostRule",
                        "is false. Default: 40 (vanilla).")
                .defineInRange("tooExpensiveThreshold", 40, 1, 1000000);

        BUILDER.pop();

        SPEC = BUILDER.build();
    }

    /**
     * Max level of the Efficiency enchantment, resolved from {@link #EFFICIENCY_MAX_LEVEL_TIER}.
     */
    public static int getEfficiencyMaxLevel() {
        String tier = EFFICIENCY_MAX_LEVEL_TIER.get();
        if ("low".equals(tier)) {
            return LOW_MAX_LEVEL.get();
        }
        if ("medium".equals(tier)) {
            return MEDIUM_MAX_LEVEL.get();
        }
        return HIGH_MAX_LEVEL.get();
    }

    /**
     * Whether the config has been loaded.
     * Forge allows reading config values only after the config file is loaded
     * (ModConfigEvent.Loading); calling {@code *.get()} before that throws
     * {@link IllegalStateException}. Code that may run before loading (e.g. Mixins)
     * must guard with this method.
     */
    public static boolean isLoaded() {
        return SPEC.isLoaded();
    }

    private Config() {
    }
}
